-- ==========================================
-- المدرار للمقاولات الهندسية (almadrars)
-- Database Schema for Customer & Admin Apps
-- ==========================================

-- إعادة تهيئة الجداول لضمان تطابق أنواع البيانات (UUID)
drop table if exists public.almadrars_project_stages cascade;
drop table if exists public.almadrars_requests cascade;
drop table if exists public.almadrars_services cascade;
drop table if exists public.almadrars_settings cascade;

-- 1. جدول خدمات المقاولات والتشطيبات والخرسانات (Catalog)
create table public.almadrars_services (
    id uuid primary key default gen_random_uuid(),
    title text not null,
    category text not null, -- تشطيبات وديكور، صب وخرسانات مسلحة، تسليم مفتاح
    description text,
    image_url text,
    projects_count integer not null default 0,
    is_available boolean not null default true,
    created_at timestamptz not null default now()
);

alter table public.almadrars_services enable row level security;

drop policy if exists "almadrars_services_select_authenticated" on public.almadrars_services;
create policy "almadrars_services_select_authenticated" on public.almadrars_services
    for select to authenticated using (true);

drop policy if exists "almadrars_services_admin_all" on public.almadrars_services;
create policy "almadrars_services_admin_all" on public.almadrars_services
    for all to authenticated using (public.almadrars_is_admin()) with check (public.almadrars_is_admin());


-- 2. جدول طلبات المعاينة والمشاريع والتسعير (Customer Data)
create table public.almadrars_requests (
    id uuid primary key default gen_random_uuid(),
    customer_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
    request_number text not null, -- e.g. MD-9042, MD-8841
    service_id uuid references public.almadrars_services(id) on delete set null,
    service_type text not null, -- نوع الخدمة المطلوبة
    location text not null, -- المدينة والحي
    area_sqm numeric, -- المساحة التقديرية (متر مربع)
    details text, -- تفاصيل المشروع والاحتياجات
    attachments jsonb not null default '[]'::jsonb, -- أسماء وصور ومخططات الخرسانات والمبنى
    status text not null default 'pending_review', -- pending_review (قيد المراجعة), priced (تم التسعير), in_progress (قيد التنفيذ), completed (مكتمل)
    status_notes text, -- ملاحظات التحديث للزبون
    estimated_cost numeric(12,2), -- التكلفة التقديرية / عرض السعر (دينار ليبي)
    estimated_duration text, -- المدة التقديرية للتنفيذ (أيام/أشهر)
    technical_specs text, -- المواصفات الفنية المعتمدة للمشروع
    completion_percentage integer not null default 0, -- نسبة الإنجاز الميداني
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now()
);

alter table public.almadrars_requests enable row level security;

drop policy if exists "almadrars_requests_customer_select" on public.almadrars_requests;
create policy "almadrars_requests_customer_select" on public.almadrars_requests
    for select to authenticated using (customer_id = auth.uid());

drop policy if exists "almadrars_requests_customer_insert" on public.almadrars_requests;
create policy "almadrars_requests_customer_insert" on public.almadrars_requests
    for insert to authenticated with check (customer_id = auth.uid());

drop policy if exists "almadrars_requests_customer_update" on public.almadrars_requests;
create policy "almadrars_requests_customer_update" on public.almadrars_requests
    for update to authenticated using (customer_id = auth.uid()) with check (customer_id = auth.uid());

drop policy if exists "almadrars_requests_admin_all" on public.almadrars_requests;
create policy "almadrars_requests_admin_all" on public.almadrars_requests
    for all to authenticated using (public.almadrars_is_admin()) with check (public.almadrars_is_admin());


-- 3. جدول مراحل تتبع المشروعات (Project Tracking Stages)
create table public.almadrars_project_stages (
    id uuid primary key default gen_random_uuid(),
    customer_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
    request_id uuid not null references public.almadrars_requests(id) on delete cascade,
    stage_key text not null, -- inspection, priced, in_progress, completed
    stage_title text not null,
    stage_description text,
    is_current boolean not null default false,
    is_completed boolean not null default false,
    created_at timestamptz not null default now()
);

alter table public.almadrars_project_stages enable row level security;

drop policy if exists "almadrars_project_stages_customer_select" on public.almadrars_project_stages;
create policy "almadrars_project_stages_customer_select" on public.almadrars_project_stages
    for select to authenticated using (customer_id = auth.uid());

drop policy if exists "almadrars_project_stages_customer_insert" on public.almadrars_project_stages;
create policy "almadrars_project_stages_customer_insert" on public.almadrars_project_stages
    for insert to authenticated with check (customer_id = auth.uid());

drop policy if exists "almadrars_project_stages_admin_all" on public.almadrars_project_stages;
create policy "almadrars_project_stages_admin_all" on public.almadrars_project_stages
    for all to authenticated using (public.almadrars_is_admin()) with check (public.almadrars_is_admin());


-- 4. جدول إعدادات النظام ومزامنة قاعدة البيانات الإدارية (Admin Config)
create table public.almadrars_settings (
    id uuid primary key default gen_random_uuid(),
    key text unique not null,
    value jsonb not null,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now()
);

alter table public.almadrars_settings enable row level security;

drop policy if exists "almadrars_settings_select_authenticated" on public.almadrars_settings;
create policy "almadrars_settings_select_authenticated" on public.almadrars_settings
    for select to authenticated using (true);

drop policy if exists "almadrars_settings_admin_all" on public.almadrars_settings;
create policy "almadrars_settings_admin_all" on public.almadrars_settings
    for all to authenticated using (public.almadrars_is_admin()) with check (public.almadrars_is_admin());


